/* Fantasy Intelligence Engine V9.1 remaining-draft Monte Carlo worker.
 * Pure-data worker. Main thread serializes canonical slot eligibility and the
 * union of available + rostered players. Candidate alternatives share the
 * same random draft worlds (common random numbers) to reduce comparison noise.
 */
'use strict';
let cancelled=false;
function finite(x){const v=Number(x);return Number.isFinite(v)?v:null;}
function clamp(x,a,b){return Math.max(a,Math.min(b,x));}
function mean(xs){return xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;}
function hashSeed(str){let h=2166136261>>>0;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function rngFor(str){let a=hashSeed(str)||1;return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;};}
function normal(rng){const u=Math.max(1e-12,rng()),v=Math.max(1e-12,rng());return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);}
function starterSlots(xs,ctx){const slotMap=ctx.slotEligibility||{};return (xs||[]).map(x=>String(x).toUpperCase()).filter(x=>Array.isArray(slotMap[x])?slotMap[x].length>0:!['BN','BENCH','IR','TAXI','RESERVE'].includes(x));}
function eligible(pos,slot,ctx){const arr=ctx.slotEligibility?.[String(slot).toUpperCase()];return Array.isArray(arr)&&arr.includes(String(pos).toUpperCase());}
function hungarianMin(cost){const n=cost.length,m=cost[0]?.length||0;if(!n||!m)return[];const u=Array(n+1).fill(0),v=Array(m+1).fill(0),p=Array(m+1).fill(0),way=Array(m+1).fill(0);for(let i=1;i<=n;i++){p[0]=i;let j0=0;const minv=Array(m+1).fill(Infinity),used=Array(m+1).fill(false);do{used[j0]=true;const i0=p[j0];let delta=Infinity,j1=0;for(let j=1;j<=m;j++)if(!used[j]){const cur=cost[i0-1][j-1]-u[i0]-v[j];if(cur<minv[j]){minv[j]=cur;way[j]=j0;}if(minv[j]<delta){delta=minv[j];j1=j;}}for(let j=0;j<=m;j++)if(used[j]){u[p[j]]+=delta;v[j]-=delta;}else minv[j]-=delta;j0=j1;}while(p[j0]!==0);do{const j1=way[j0];p[j0]=p[j1];j0=j1;}while(j0!==0);}const ans=Array(n).fill(-1);for(let j=1;j<=m;j++)if(p[j])ans[p[j]-1]=j-1;return ans;}
function lineupAssignment(pool,slots,key,ctx){if(!slots.length)return{total:0,selectedIds:[],unfilledSlots:[]};const players=pool||[],m=Math.max(players.length,slots.length),NEG=-1e6;const matrix=slots.map(slot=>Array.from({length:m},(_,j)=>{if(j>=players.length)return 0;const p=players[j],val=finite(p[key])??0;return eligible(p.position,slot,ctx)?val:NEG;}));const maxVal=Math.max(0,...matrix.flat().filter(x=>x>NEG/2)),cost=matrix.map(r=>r.map(x=>x<=NEG/2?maxVal+1e5:maxVal-x)),assign=hungarianMin(cost);let total=0;const selectedIds=[],unfilledSlots=[];for(let i=0;i<assign.length;i++){const j=assign[i];if(j>=0&&j<players.length&&matrix[i][j]>NEG/2){total+=matrix[i][j];selectedIds.push(players[j].id);}else unfilledSlots.push(slots[i]);}return{total,selectedIds,unfilledSlots};}
function rosterUtility(pool,ctx){const slots=starterSlots(ctx.rosterPositions,ctx);const lineMean=lineupAssignment(pool,slots,'mean',ctx),lineFloor=lineupAssignment(pool,slots,'floor',ctx),lineCeil=lineupAssignment(pool,slots,'ceiling',ctx),lineUtility=lineupAssignment(pool,slots,'utility',ctx);let starterTotal,selected;
  if(ctx.format==='CHOPPED'){starterTotal=.55*lineMean.total+.45*lineFloor.total;selected=new Set([...lineMean.selectedIds,...lineFloor.selectedIds]);}
  else if(String(ctx.format).includes('BESTBALL')){starterTotal=.45*lineMean.total+.55*lineCeil.total;selected=new Set([...lineMean.selectedIds,...lineCeil.selectedIds]);}
  else if(String(ctx.format).includes('DYNASTY')){starterTotal=lineUtility.total;selected=new Set(lineUtility.selectedIds);}
  else{starterTotal=lineMean.total;selected=new Set(lineMean.selectedIds);}
  const bench=(pool||[]).filter(p=>!selected.has(p.id));const benchBonus=bench.map(p=>Math.max(0,finite(p.vor)??0)).sort((a,b)=>b-a).reduce((a,b)=>a+b,0)*.12;return{total:starterTotal+benchBonus,starterTotal,starterIds:[...selected],benchIds:bench.map(p=>p.id)};
}
function posCount(pool,pos){return pool.reduce((n,p)=>n+(p.position===pos?1:0),0);}
function demandFor(pos,ctx){const slots=starterSlots(ctx.rosterPositions,ctx);let n=0;for(const slot of slots)if(eligible(pos,slot,ctx))n++;return Math.max(.5,n/Math.max(1,['RB','WR','TE'].includes(pos)?2:1));}
function needAdjustment(pool,p,round,ctx){const demand=demandFor(p.position,ctx),have=posCount(pool,p.position),short=Math.max(0,Math.ceil(demand)-have),over=Math.max(0,have-Math.ceil(demand)-1);let a=short*(round<=6?8:5)-over*3;if((p.position==='QB'||p.position==='TE')&&demand<1.25&&have>=1)a-=4;return clamp(a,-10,18);}
function managerReach(ctx,rid,p){const uid=String(ctx.rosterOwner?.[rid]||''),m=ctx.history?.managers?.[uid];if(!m)return 0;const vals=[];const pb=(m.posBias||[]).find(x=>x.pos===p.position&&x.n>=2);if(pb&&finite(pb.delta)!==null)vals.push(Number(pb.delta));const canonical=(m.playerBias||[]).find(x=>String(x.playerId||'')===String(p.id)&&x.n>=2);const legacy=!canonical?(m.playerBias||[]).find(x=>String(x.name||'').toLowerCase()===String(p.name||'').toLowerCase()&&x.n>=2):null;const fav=canonical||legacy;if(fav&&finite(fav.delta)!==null)vals.push(Number(fav.delta));return vals.length?clamp(mean(vals),-15,15):0;}
function bestFromShortlist(sorted,available,limit,scoreFn){let best=null,bestScore=-Infinity,n=0;for(const item of sorted){if(!available.has(item.id))continue;n++;const s=scoreFn(item,item);if(s>bestScore){bestScore=s;best=item;}if(n>=limit)break;}return best;}
function simulateCandidate(cid,ctx,simIndex){/* Same random world for every candidate. */const rng=rngFor(`${ctx.seed}|${simIndex}`),byId=new Map(ctx.players.map(p=>[String(p.id),p])),available=new Set(ctx.players.filter(p=>p.draftAvailable!==false).map(p=>String(p.id))),rosters={};for(const [k,ids]of Object.entries(ctx.basePools||{})){rosters[k]=(ids||[]).map(id=>byId.get(String(id))).filter(Boolean);if(rosters[k].length!==(ids||[]).length)throw new Error(`worker base roster ${k} could not be reconstructed`);}const candidate=byId.get(String(cid));if(!candidate||!available.has(String(cid)))return null;rosters[ctx.rosterId]=(rosters[ctx.rosterId]||[]).concat(candidate);available.delete(String(cid));const latent=ctx.players.filter(p=>p.draftAvailable!==false).map(p=>{const sigma=clamp(6+Math.max(0,p.market-ctx.startPick)*.035,6,18);return{...p,latent:p.market+normal(rng)*sigma};}).sort((a,b)=>a.latent-b.latent);for(const pick of ctx.seq){if(cancelled)return null;if(pick.pickNo<=ctx.startPick||pick.pickNo>ctx.endPick)continue;const rid=ctx.slotRoster[pick.slot];if(!rid||!available.size)continue;const rp=rosters[rid]||(rosters[rid]=[]);let choice;if(Number(rid)===Number(ctx.rosterId)){choice=bestFromShortlist(latent,available,42,p=>p.decision+needAdjustment(rp,p,pick.round,ctx)*1.4-Math.max(0,p.market-pick.pickNo)*.08);}else{choice=bestFromShortlist(latent,available,28,p=>-p.latent+managerReach(ctx,rid,p)*.75+needAdjustment(rp,p,pick.round,ctx)*.65);}if(!choice)continue;available.delete(choice.id);rp.push(choice);}return rosterUtility(rosters[ctx.rosterId]||[],ctx);}
function run(msg){cancelled=false;const ctx=msg.context,results=[];for(const cid of msg.candidateIds||[]){const vals=[];for(let i=msg.startIndex;i<msg.startIndex+msg.count;i++){if(cancelled)return;const v=simulateCandidate(String(cid),ctx,i);if(v&&finite(v.total)!==null)vals.push(Number(v.total));}results.push({id:String(cid),values:vals});}postMessage({type:'batch',jobId:msg.jobId,startIndex:msg.startIndex,count:msg.count,results});}
onmessage=e=>{const m=e.data||{};if(m.type==='cancel'){cancelled=true;return;}if(m.type==='run')run(m);};
